# Builds the Release configuration from the terminal (no IDE), then produces
# TempLogPro.bin/.hex with objcopy and prints the SHA-256 of each image.
# Uses the makefiles generated by STM32CubeIDE in Release/. The list of
# top-level Src/*.c files in Release/Src/subdir.mk and Release/objects.list is
# regenerated first (same format as CubeIDE), so added or removed files in Src/
# need no IDE build. Sources in Src subfolders still come from the IDE files.
param(
    [switch]$Clean
)

$ErrorActionPreference = 'Stop'
$root = Split-Path -Parent $PSScriptRoot
$plugins = 'C:\ST\STM32CubeIDE_2.2.0\STM32CubeIDE\plugins'
$gccBin = (Get-ChildItem $plugins -Directory -Filter 'com.st.stm32cube.ide.mcu.externaltools.gnu-tools-for-stm32.*' |
           Sort-Object Name -Descending | Select-Object -First 1).FullName + '\tools\bin'
$makeBin = (Get-ChildItem $plugins -Directory -Filter 'com.st.stm32cube.ide.mcu.externaltools.make.*' |
            Sort-Object Name -Descending | Select-Object -First 1).FullName + '\tools\bin'

if (-not (Test-Path "$gccBin\arm-none-eabi-gcc.exe")) { throw "arm-none-eabi-gcc not found under $plugins" }
if (-not (Test-Path "$makeBin\make.exe")) { throw "make not found under $plugins" }

$env:PATH = "$gccBin;$makeBin;$env:PATH"
$release = Join-Path $root 'Release'

function Sync-SrcList {
    $names = Get-ChildItem (Join-Path $root 'Src') -File -Filter '*.c' |
             Sort-Object Name | ForEach-Object { $_.BaseName }
    $subdir = Join-Path $release 'Src\subdir.mk'
    $text = [IO.File]::ReadAllText($subdir)
    $nl = "`r`n"
    if (-not $text.Contains($nl)) { $nl = "`n" }
    $lists = @{
        'C_SRCS' = $names | ForEach-Object { "../Src/$_.c" }
        'OBJS'   = $names | ForEach-Object { "./Src/$_.o" }
        'C_DEPS' = $names | ForEach-Object { "./Src/$_.d" }
    }
    foreach ($key in $lists.Keys) {
        $body = ($lists[$key] -join " \$nl") + " $nl"
        $pattern = "(?s)$key \+= \\\r?\n.*?\r?\n\r?\n"
        if ($text -notmatch $pattern) { throw "Unexpected format of $subdir ($key)" }
        $text = [regex]::Replace($text, $pattern, "$key += \$nl$body$nl", 1)
    }
    $clean = ($names | ForEach-Object { "./Src/$_.cyclo ./Src/$_.d ./Src/$_.o ./Src/$_.su" }) -join ' '
    $text = [regex]::Replace($text, '(?m)^(\t-\$\(RM\) ).*\./Src/[^/\s]+\.su.*$', "`${1}$clean")
    [IO.File]::WriteAllText($subdir, $text)

    $objects = Join-Path $release 'objects.list'
    $other = Get-Content $objects | Where-Object { $_ -notmatch '^"\./Src/[^/]+\.o"$' }
    $own = $names | ForEach-Object { "`"./Src/$_.o`"" }
    [IO.File]::WriteAllLines($objects, [string[]]($own + $other))
}

Sync-SrcList

# CubeIDE writes the linker script into Release/makefile as an absolute path.
# Point it at this folder so a restored backup builds from any location.
$makefile = Join-Path $release 'makefile'
$mk = [IO.File]::ReadAllText($makefile)
$ld = Join-Path $root 'STM32L152RCTX_FLASH.ld'
$fixed = [regex]::Replace($mk, '[A-Za-z]:[\\/][^"\s]*?STM32L152RCTX_FLASH\.ld', { param($m) $ld })
if ($fixed -ne $mk) { [IO.File]::WriteAllText($makefile, $fixed) }

# The HTML panel source is panel/templogpro.html; regenerate its C literals.
& python (Join-Path $root 'tools\gen_panel.py')
if ($LASTEXITCODE -ne 0) { throw 'gen_panel.py failed' }

if ($Clean) {
    Get-ChildItem $release -Recurse -Include '*.o','*.d','*.su','*.cyclo' | Remove-Item -Force
}

& make.exe -C $release -j8 all
if ($LASTEXITCODE -ne 0) { throw "make failed with exit code $LASTEXITCODE" }

$elf = Join-Path $release 'TempLogPro.elf'
& arm-none-eabi-objcopy.exe -O binary $elf (Join-Path $release 'TempLogPro.bin')
if ($LASTEXITCODE -ne 0) { throw 'objcopy (bin) failed' }
& arm-none-eabi-objcopy.exe -O ihex $elf (Join-Path $release 'TempLogPro.hex')
if ($LASTEXITCODE -ne 0) { throw 'objcopy (hex) failed' }

& arm-none-eabi-size.exe $elf
foreach ($ext in 'elf', 'bin', 'hex') {
    $file = Join-Path $release "TempLogPro.$ext"
    '{0}  {1}' -f (Get-FileHash $file -Algorithm SHA256).Hash.ToLower(), "Release/TempLogPro.$ext"
}
